$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$out=$PSScriptRoot;$repo=(Resolve-Path "$out/../../..").Path
$files=@();foreach($p in Get-ChildItem $out -File -Filter *.png){$b=[Drawing.Bitmap]::new($p.FullName);$files+=@{file=$p.Name;size=@($b.Width,$b.Height);sha256=(Get-FileHash -Algorithm SHA256 $p.FullName).Hash.ToLower();kind=$(if($p.Name -match 'generated|source'){'generated_source'}elseif($p.Name -match '_4x'){'preview'}elseif($p.Name -match '_native'){'native'}else{'delivery'})};$b.Dispose()}
$sheets=@(
 @{file='hero_walk_run_grid.png';native='hero_walk_run_grid_native.png';columns=4;rows=4;frame_count=16;row_order=@('back_walk','left_walk','left_run','front_walk');frame_order='row-major, left to right; preserve existing four gait phases in each row';fps_by_row=@(6,6,8,6);mirror_right=$true;existing_walk_mirror_phase=@(2,3,0,1)},
 @{file='hero_back_idle.png';native='hero_back_idle_native.png';columns=1;rows=1;frame_count=1;frame_order=@('back_idle');derived_from='hero_command_native.png frame 0'},
 @{file='hero_command.png';native='hero_command_native.png';columns=3;rows=1;frame_count=3;frame_order=@('back_ready','right_hand_to_temple','right_arm_command');fps=6;playback='hold_last';mirror_right=$false}
)
$sourcePaths=@('Docs/GDD/Concept_Beacon_v1.md','Docs/References/codex_k107_v1/comparison_front_night065_game_4x.png','Docs/References/codex_k107_v1/variant_a_front_native.png','Docs/References/codex_k107_v1/variant_a_portrait.png','Docs/References/beacon_game_20261022/05_pf_night_clean.png')
foreach($n in @('hero_walk_run_grid','hero_back_idle','hero_command')){foreach($suffix in @('','_normal')){$sourcePaths+="Game/Assets/_Project/Art/Characters/Hero/$n$suffix.png"};$sourcePaths+="Game/Assets/_Project/Art/Battle/Resources/BattleArt/Spec/${n}_spec.png"}
foreach($e in @('neutral','determined','surprised','tired')){$sourcePaths+="Game/Assets/_Project/Story/Resources/StoryArt/portrait_hero_$e.png"}
$sourcePaths+='Game/Assets/_Project/Art/UI/Resources/HudArt/Tutorial/officer_expressions.png'
$sources=@();foreach($p in $sourcePaths){$sources+=@{path=$p;sha256=(Get-FileHash -Algorithm SHA256 "$repo/$p").Hash.ToLower()}}
$manifest=[ordered]@{card='K-109';hero='Lumen Pharos';variant='A';stage='asset_delivery_integration_pending';generation_tool='image_gen.imagegen built-in';design_basis='K-107 selected comparison A; existing hero proportions. Not variant_a_generated.png as a proportion reference.';native=@{cell=@(96,128);body_axis_x=48;foot_pivot_top_left=@(48,120);last_opaque_y=119;figure_height=73};game=@{cell=@(288,384);foot_pivot_top_left=@(144,360);unity_normalized_bottom_left_pivot=@(.5,.0625);last_opaque_y=359;scale=3;filter='nearest';existing_game_cell_already_same=$true};sheets=$sheets;maps=@{normal_naming='[sheet]_normal.png';normal_encoding='RGB tangent-space, +Y up; opaque flat background (128,128,255), silhouette-derived inward bevel; use color alpha';normal_color_space='linear';spec_naming='[sheet]_spec.png';spec_encoding='opaque grayscale; cloth 12/255, brass and trim 220/255, warm lantern glass 150/255; restrict metal classification to torso/belt';spec_color_space='linear';same_layout_as_color=$true};portraits=@{canvas=@(256,384);framing='full body, same legacy canvas and approximate head/foot margins';order=@('neutral','determined','surprised','tired');working_grid=@(64,96);scale=4;foot_boundary_y=356};tutorial=@{file='officer_expressions.png';canvas=@(576,144);cell=@(144,144);columns=4;rows=1;frame_order=@('neutral','explaining_raised_finger','urgent','pleased');working_cell=@(48,48);scale=3};review=@{path='_HTML/6_그림_화면/codex_K-109_루멘전체그림_v1.html';self_contained=$true;night_rgb_multiplier=.65;background='Docs/References/beacon_game_20261022/05_pf_night_clean.png';background_already_lit=$true;composite_not_unity_capture=$true;browser_render_verified=$false;runtime_verification='review_validation.json'};source_art=$sources;files=$files;verification='validation.json';game_modified=$false;unity_executed=$false;git_writes=$false;leftovers=@('Claude integration and actual Unity lighting/motion verification','User visual approval','Browser screenshot verification unavailable in this session')}
$manifest|ConvertTo-Json -Depth 12|Set-Content -Encoding UTF8 "$out/manifest.json"
Write-Output "매니페스트 생성: PNG $($files.Count)개"
